    background:linear-gradient(165deg,#131b2e 0%,var(--card) 60%);
    border:1px solid var(--border);
    border-radius:24px;
    padding:26px 26px 24px;
    box-shadow:0 30px 70px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.05);
    overflow:hidden;
    transition:box-shadow .4s ease;
  }
  .card::before{ /* top gradient glow line */
    content:"";position:absolute;inset:0 0 auto 0;height:1px;
    background:linear-gradient(90deg,transparent,rgba(99,102,241,.9),rgba(34,211,238,.9),transparent);
  }
  .card.focusing{
    box-shadow:0 0 0 1px rgba(52,211,153,.25), 0 30px 80px rgba(52,211,153,.12), 0 30px 70px rgba(0,0,0,.6);
  }

  /* header */
  .head{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}
  .head h1{font-size:15px;font-weight:650;letter-spacing:.2px}
  .head .sub{font-size:11.5px;color:var(--muted);margin-top:2px}
  .status{
    display:flex;align-items:center;gap:7px;
    font-size:11px;color:var(--muted);
    border:1px solid var(--border);border-radius:999px;
    padding:5px 11px;background:rgba(255,255,255,.03);
  }
  .dot{width:7px;height:7px;border-radius:50%;background:#fbbf24;box-shadow:0 0 8px rgba(251,191,36,.8)}
  .card.focusing .dot{background:var(--green);box-shadow:0 0 10px var(--green);animation:pulse 1.6s infinite}
  .card.focusing .status{color:var(--green)}
  @keyframes pulse{0%,100%{transform:scale(1);opacity:1}50%{transform:scale(1.35);opacity:.6}}

  /* score ring */
  .score-wrap{display:flex;align-items:center;gap:20px;margin-bottom:22px}
  .ring-box{position:relative;width:132px;height:132px;flex:none}
  .ring-center{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center}
  .ring-center .num{font-size:34px;font-weight:750;line-height:1;font-variant-numeric:tabular-nums}
  .ring-center .of{font-size:11px;color:var(--muted);margin-top:3px}
  .score-meta{flex:1}
  .score-meta .label{font-size:12px;color:var(--muted);margin-bottom:8px}
  .chip{
    display:inline-flex;align-items:center;gap:5px;
    font-size:12px;font-weight:600;color:var(--green);
    background:rgba(52,211,153,.1);border:1px solid rgba(52,211,153,.22);
    padding:4px 10px;border-radius:8px;margin-bottom:14px;
  }
  .mini-stats{display:flex;gap:8px}
  .stat{flex:1;background:rgba(255,255,255,.03);border:1px solid var(--border);border-radius:12px;padding:9px 10px}
  .stat b{display:block;font-size:15px;font-weight:700}
  .stat span{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.6px}

  /* sparkline */
  .trend{margin-bottom:22px}
  .trend-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px}
  .trend-head h2{font-size:12.5px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:.8px}
  .trend-head .avg{font-size:12px;color:var(--muted)}
  .trend-head .avg b{color:var(--text)}
  .spark-box{position:relative}
  .spark-box svg{width:100%;height:78px;display:block;overflow:visible;cursor:crosshair}
  .tip{
    position:absolute;pointer-events:none;transform:translate(-50%,-130%);
    background:#1a2340;border:1px solid var(--border);border-radius:8px;
    padding:4px 9px;font-size:11.5px;font-weight:600;white-space:nowrap;
    opacity:0;transition:opacity .15s;
  }
  .days{display:flex;justify-content:space-between;margin-top:6px;font-size:10.5px;color:var(--muted)}
  .days span{flex:1;text-align:center}
  .days .today{color:var(--a2);font-weight:700}

  /* button */
  .btn{
    width:100%;border:none;cursor:pointer;
    display:flex;align-items:center;justify-content:center;gap:10px;
    padding:15px;border-radius:16px;
    font-size:15px;font-weight:700;letter-spacing:.3px;color:#fff;
    background:linear-gradient(135deg,var(--a1),var(--a2));
    box-shadow:0 10px 28px rgba(99,102,241,.35);
    transition:transform .15s ease, box-shadow .3s ease, background .3s ease;
    font-family:inherit;font-variant-numeric:tabular-nums;
  }
  .btn:hover{transform:translateY(-2px);box-shadow:0 14px 34px rgba(99,102,241,.5)}
  .btn:active{transform:translateY(0) scale(.98)}
  .btn.active{background:linear-gradient(135deg,#e11d48,#fb7185);box-shadow:0 10px 28px rgba(225,29,72,.35)}
  .btn svg{width:15px;height:15px;flex:none}
  .elapsed{font-variant-numeric:tabular-nums;opacity:.95}
</style>
</head>
<body>

<div class="card" id="card">
  <div class="head">
    <div>
      <h1>Daily Focus</h1>
      <div class="sub" id="dateLine">—</div>
    </div>
    <div class="status"><span class="dot"></span><span id="statusText">Idle</span></div>
  </div>

  <div class="score-wrap">
    <div class="ring-box">
      <svg width="132" height="132" viewBox="0 0 132 132">
        <defs>
          <linearGradient id="ringGrad" x1="0" y1="0" x2="1" y2="1">
            <stop offset="0%" stop-color="#6366f1"/>
            <stop offset="100%" stop-color="#22d3ee"/>
          </linearGradient>
        </defs>
        <circle cx="66" cy="66" r="54" fill="none" stroke="rgba(255,255,255,.06)" stroke-width="10"/>
        <circle id="ring" cx="66" cy="66" r="54" fill="none" stroke="url(#ringGrad)" stroke-width="10"
                stroke-linecap="round" transform="rotate(-90 66 66)"/>
      </svg>
      <div class="ring-center">
        <div class="num" id="scoreNum">0</div>
        <div class="of">/ 100 focus</div>
      </div>
    </div>
    <div class="score-meta">
      <div class="label">Today's score</div>
      <div class="chip" id="deltaChip">▲ 0%</div>
      <div class="mini-stats">
        <div class="stat"><b id="streak">0</b><span>Streak</span></div>
        <div class="stat"><b id="best">0</b><span>Best</span></div>
      </div>
    </div>
  </div>

  <div class="trend">
    <div class="trend-head">
      <h2>Weekly Trend</h2>
      <div class="avg">avg <b id="avgVal">—</b></div>
    </div>
    <div class="spark-box">
      <svg id="spark" viewBox="0 0 320 78" preserveAspectRatio="none" aria-label="Weekly focus trend"></svg>
      <div class="tip" id="tip"></div>
    </div>
    <div class="days" id="days"></div>
  </div>

  <button class="btn" id="focusBtn">
    <svg viewBox="0 0 24 24" fill="currentColor" id="btnIcon"><path d="M8 5.5v13l11-6.5-11-6.5z"/></svg>
    <span id="btnLabel">Start Focus</span>
  </button>
</div>

<script>
(function(){
  "use strict";

  /* ---------- Data ---------- */
  const WEEK = [
    { d:"Mon", v:62 }, { d:"Tue", v:74 }, { d:"Wed", v:58 },
    { d:"Thu", v:81 }, { d:"Fri", v:90 }, { d:"Sat", v:76 },
    { d:"Sun", v:87 }
  ];
  const score = WEEK[WEEK.length-1].v;
  const prev  = WEEK[WEEK.length-2].v;
  const avg   = Math.round(WEEK.reduce((s,p)=>s+p.v,0)/WEEK.length);
  const best  = Math.max(...WEEK.map(p=>p.v));
  let streak  = 0;
  for (let i=WEEK.length-1;i>=0 && WEEK[i].v>=70;i--) streak++;

  /* ---------- Header date ---------- */
  document.getElementById("dateLine").textContent =
    new Date().toLocaleDateString(undefined,{weekday:"long",month:"short",day:"numeric"});

  /* ---------- Score ring + count-up ---------- */
  const ring = document.getElementById("ring");
  const C = 2*Math.PI*54;
  ring.style.strokeDasharray = C;
  ring.style.strokeDashoffset = C;

  const numEl = document.getElementById("scoreNum");
  const t0 = performance.now(), DUR = 1200;
  (function tick(now){
    const p = Math.min((now-t0)/DUR,1);
    const e = 1-Math.pow(1-p,3);                 // easeOutCubic
    numEl.textContent = Math.round(score*e);
    ring.style.strokeDashoffset = C*(1-(score/100)*e);
    if (p<1) requestAnimationFrame(tick);
  })(t0);

  /* ---------- Delta chip + stats ---------- */
  const delta = Math.round((score-prev)/prev*100);
  const chip = document.getElementById("deltaChip");
  const up = delta >= 0;
  chip.textContent = (up?"▲ ":"▼ ") + Math.abs(delta) + "% vs yesterday";
  if (!up){
    chip.style.color = "var(--red)";
    chip.style.background = "rgba(251,113,133,.1)";
    chip.style.borderColor = "rgba(251,113,133,.25)";
  }
  document.getElementById("streak").textContent = streak + "d";
  document.getElementById("best").textContent = best;
  document.getElementById("avgVal").textContent = avg;

  /* ---------- Sparkline ---------- */
  const svg = document.getElementById("spark");
  const NS = "http://www.w3.org/2000/svg";
  const W=320, H=78, PAD=8;
  const xs = i => PAD + i*(W-2*PAD)/(WEEK.length-1);
  const ys = v => H-10 - (v-40)/(100-40)*(H-24);   // scale 40–100

  const pts = WEEK.map((p,i)=>({x:+xs(i).toFixed(2), y:+ys(p.v).toFixed(2)}));

  function smooth(p){                             // Catmull-Rom → Bézier
    let d = `M ${p[0].x} ${p[0].y}`;
    for (let i=0;i<p.length-1;i++){
      const a=p[Math.max(0,i-1)], b=p[i], c=p[i+1], e=p[Math.min(p.length-1,i+2)];
      const c1x=b.x+(c.x-a.x)/6, c1y=b.y+(c.y-a.y)/6;
      const c2x=c.x-(e.x-b.x)/6, c2y=c.y-(e.y-b.y)/6;
      d+=` C ${c1x.toFixed(2)} ${c1y.toFixed(2)} ${c2x.toFixed(2)} ${c2y.toFixed(2)} ${c.x} ${c.y}`;
    }
    return d;
  }

  svg.innerHTML = `
    <defs>
      <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
        <stop offset="0%" stop-color="#6366f1"/><stop offset="100%" stop-color="#22d3ee"/>
      </linearGradient>
      <linearGradient id="areaGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="rgba(99,102,241,.35)"/>
        <stop offset="100%" stop-color="rgba(34,211,238,0)"/>
      </linearGradient>
    </defs>`;

  const lineD = smooth(pts);
  const area = document.createElementNS(NS,"path");
  area.setAttribute("d", lineD + ` L ${pts[pts.length-1].x} ${H} L ${pts[0].x} ${H} Z`);
  area.setAttribute("fill","url(#areaGrad)");
  svg.appendChild(area);

  const line = document.createElementNS(NS,"path");
  line.setAttribute("d", lineD);
  line.setAttribute("fill","none");
  line.setAttribute("stroke","url(#lineGrad)");
  line.setAttribute("stroke-width","2.5");
  line.setAttribute("stroke-linecap","round");
  svg.appendChild(line);

  // draw-on animation
  const len = line.getTotalLength();
  line.style.strokeDasharray = len;
  line.style.strokeDashoffset = len;
  line.getBoundingClientRect();                   // force reflow
  line.style.transition = "stroke-dashoffset 1.3s ease .2s";
  line.style.strokeDashoffset = "0";

  // end-point glow dot + hover dot
  const mkDot=(r,fill,extra)=>{const c=document.createElementNS(NS,"circle");c.setAttribute("r",r);c.setAttribute("fill",fill);if(extra)Object.entries(extra).forEach(([k,v])=>c.setAttribute(k,v));return c;};
  const last = pts[pts.length-1];
  const halo = mkDot(9,"rgba(34,211,238,.18)"); halo.setAttribute("cx",last.x); halo.setAttribute("cy",last.y);
  const end  = mkDot(4,"#22d3ee",{stroke:"#0e1422","stroke-width":"2"}); end.setAttribute("cx",last.x); end.setAttribute("cy",last.y);
  svg.appendChild(halo); svg.appendChild(end);

  const hover = mkDot(4.5,"#fff",{stroke:"#6366f1","stroke-width":"2"});
  hover.style.opacity="0"; svg.appendChild(hover);

  // hover tooltip
  const tip = document.getElementById("tip");
  svg.addEventListener("mousemove", e=>{
    const r = svg.getBoundingClientRect();
    const mx = (e.clientX-r.left)/r.width*W;
    let ni = 0;
    pts.forEach((p,i)=>{ if(Math.abs(p.x-mx)<Math.abs(pts[ni].x-mx)) ni=i; });
    const p = pts[ni];
    hover.setAttribute("cx",p.x); hover.setAttribute("cy",p.y); hover.style.opacity="1";
    tip.textContent = WEEK[ni].d+" · "+WEEK[ni].v;
    tip.style.left = (p.x/W*100)+"%";
    tip.style.top  = (p.y/H*100)+"%";
    tip.style.opacity="1";
  });
  svg.addEventListener("mouseleave", ()=>{ tip.style.opacity="0"; hover.style.opacity="0"; });

  // day labels
  document.getElementById("days").innerHTML = WEEK.map((p,i)=>
    `<span class="${i===WEEK.length-1?"today":""}">${i===WEEK.length-1?"Today":p.d[0]}</span>`).join("");

  /* ---------- Focus button / session timer ---------- */
  const card  = document.getElementById("card");
  const btn   = document.getElementById("focusBtn");
  const lbl   = document.getElementById("btnLabel");
  const icon  = document.getElementById("btnIcon");
  const statusText = document.getElementById("statusText");
  let timer=null, tStart=0;

  const fmt = s=>{
    const h=Math.floor(s/3600), m=Math.floor(s%3600/60), ss=s%60;
    const pad=n=>String(n).padStart(2,"0");
    return (h?pad(h)+":":"")+pad(m)+":"+pad(ss);
  };

  btn.addEventListener("click", ()=>{
    if (timer){                                    // end session
      clearInterval(timer); timer=null;
      card.classList.remove("focusing");
      btn.classList.remove("active");
      statusText.textContent="Idle";
      lbl.textContent="Start Focus";
      icon.innerHTML='<path d="M8 5.5v13l11-6.5-11-6.5z"/>';
    } else {                                       // start session
      tStart=Date.now();
      card.classList.add("focusing");
      btn.classList.add("active");
      statusText.textContent="In session";
      icon.innerHTML='<rect x="6" y="6" width="12" height="12" rx="2"/>';
      const upd=()=>lbl.innerHTML=`Focusing · <span class="elapsed">${fmt(Math.floor((Date.now()-tStart)/1000))}</span> — End`;
      upd(); timer=setInterval(upd,1000);
    }
  });
})();
</script>
</body>
</html>
```

What's included:

- **Focus score ring** — SVG progress ring with gradient stroke, animated count-up from 0 to today's score with an easeOutCubic easing
- **Weekly sparkline** — smooth Catmull-Rom curve with gradient area fill, draw-on animation, glowing endpoint for today, and a hover tooltip showing each day's value
- **Start Focus button** — fully functional: clicking it starts a live session timer, flips the button to a red "End" state, pulses the status dot green, and adds a glow to the card
- **Derived stats** — day-over-day delta chip, streak counter, best score, and weekly average are all computed from the `WEEK` data array at the top of the script, so you can swap in real data by editing one array

Everything renders with inline SVG and system fonts — zero external requests.

