    <script>
        // Data for sparkline (Mon-Sun)
        const weeklyData = [65, 58, 72, 68, 80, 75, 82];
        const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

        // Generate sparkline path
        function generateSparkline() {
            const width = 350;
            const height = 80;
            const paddingX = 20;
            const paddingY = 15;
            const availableWidth = width - paddingX * 2;
            const availableHeight = height - paddingY * 2;

            const maxVal = 100;
            const minVal = 50;
            const range = maxVal - minVal;

            const points = weeklyData.map((val, i) => {
                const x = paddingX + (i / (weeklyData.length - 1)) * availableWidth;
                const y = height - paddingY - ((val - minVal) / range) * availableHeight;
                return { x, y, val };
            });

            // Smooth curve using cubic bezier
            let pathD = `M ${points[0].x} ${points[0].y}`;
            for (let i = 0; i < points.length - 1; i++) {
                const p0 = points[i];
                const p1 = points[i + 1];
                const cp1x = p0.x + (p1.x - p0.x) * 0.4;
                const cp1y = p0.y;
                const cp2x = p1.x - (p1.x - p0.x) * 0.4;
                const cp2y = p1.y;
                pathD += ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p1.x} ${p1.y}`;
            }

            // Area path
            const areaD = pathD + ` L ${points[points.length-1].x} ${height - paddingY} L ${points[0].x} ${height - paddingY} Z`;

            document.getElementById('sparkPath').setAttribute('d', pathD);
            document.getElementById('sparkArea').setAttribute('d', areaD);

            // Position dots
            points.forEach((p, i) => {
                const dot = document.getElementById(`dot${i}`);
                dot.setAttribute('cx', p.x);
                dot.setAttribute('cy', p.y);
                dot.style.animationDelay = `${1.3 + i * 0.1}s`;

                if (i === points.length - 1) {
                    dot.classList.add('active');
                }
            });
        }

        // Initialize sparkline
        generateSparkline();

        // Focus button logic
        let timerInterval = null;
        let timeLeft = 25 * 60;
        let isActive = false;

        const focusBtn = document.getElementById('focusBtn');
        const btnText = document.getElementById('btnText');
        const timerDisplay = document.getElementById('timerDisplay');

        focusBtn.addEventListener('click', () => {
            if (!isActive) {
                isActive = true;
                focusBtn.classList.add('active');
                btnText.classList.add('hidden');
                timerDisplay.classList.remove('hidden');
                timerDisplay.textContent = '25:00';

                timerInterval = setInterval(() => {
                    timeLeft--;
                    const mins = Math.floor(timeLeft / 60);
                    const secs = timeLeft % 60;
                    timerDisplay.textContent = `${mins}:${secs.toString().padStart(2, '0')}`;

                    if (timeLeft <= 0) {
                        clearInterval(timerInterval);
                        isActive = false;
                        focusBtn.classList.remove('active');
                        btnText.classList.remove('hidden');
                        timerDisplay.classList.add('hidden');
                        timeLeft = 25 * 60;
                        timerDisplay.textContent = '25:00';
                    }
                }, 1000);
            } else {
                clearInterval(timerInterval);
                isActive = false;
                focusBtn.classList.remove('active');
                btnText.classList.remove('hidden');
                timerDisplay.classList.add('hidden');
                timeLeft = 25 * 60;
            }
        });

        // Stats button interaction
        document.getElementById('statsBtn').addEventListener('click', () => {
            const values = ['4h 32m', '7', '82'];
            const targets = ['focusTime', 'sessionsCount', 'scoreValue'];
            targets.forEach((id, i) => {
                const el = document.getElementById(id);
                el.style.transition = 'all 0.3s';
                el.style.transform = 'scale(1.1)';
                setTimeout(() => el.style.transform = 'scale(1)', 200);
            });
        });

        // Set current date
        const now = new Date();
        const options = { month: 'short', day: 'numeric', year: 'numeric' };
        document.getElementById('currentDate').textContent = now.toLocaleDateString('en-US', options);

        // Animate score count
        const scoreEl = document.getElementById('scoreValue');
        const targetScore = 82;
        let currentScore = 0;
        const scoreInterval = setInterval(() => {
            currentScore += 2;
            if (currentScore >= targetScore) {
                currentScore = targetScore;
                clearInterval(scoreInterval);
            }
            scoreEl.textContent = currentScore;
        }, 25);

        // Randomize stats slightly for realism
        setTimeout(() => {
            document.getElementById('focusTime').textContent = '4h 32m';
            document.getElementById('sessionsCount').textContent = '7';
        }, 1000);
    </script>
